INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('3cbc5bce-5164-960e-fffd-316f7fa6122b'::uuid, 'Master of Business Administration (MBA) – General Technology Management Major: Automotive and Mobility Management', 'ea278536-0b01-8aef-d1e7-cbd21efb474f'::uuid, 'Berlin', '18 Months', 'View Program Description Click to expand In today’s globally connected economy, innovation plays a decisive role in determining competitiveness and business success. Internationalisation and globalisation are increasing the pressure to innovate, not only for large corporations but also for small and medium-sized enterprises (SMEs). Future managers will be challenged to keep their organisations competitive by developing market-creating innovations and implementing efficiency-enhancing strategies. These capabilities are essential to sustaining long-term growth and success. Only through continuous innovation can Germany’s economic backbone, the “Mittelstand,” with its numerous global market leaders and the renowned “Made in Germany” quality label, maintain its strong position in the global economy.', '3 or 4 year Bachelor''s Degree Min. 55%
