INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('37ac76cc-964a-6d8c-7bcc-4141b3871f0f'::uuid, 'Sports Management (Bachelor of Arts)', '051753f9-b15f-7cd5-2cbd-d58bbbae73ae'::uuid, 'Berlin', '36 Months', 'View Program Description Click to expand For many people, sport is more than just a hobby. The sports industry is gaining increasing social and economic importance and is becoming more professionalised, leading to the creation of numerous new career opportunities. The so-called “magic triangle” of sport, media, and business is driving demand for specialists and managers who can think interdisciplinarily and combine strong management skills with sport-specific expertise. The interdisciplinary B.A. Sports Management programme equips you with the necessary knowledge and skills for specialist and leadership roles in the sports industry. Core business administration concepts are combined with industry-specific insights to prepare you for a successful career in this dynamic field.', 'Higher Secondary School Min. 70%
