INSERT INTO public.degree (id, name, credits, location, language_of_study, duration, fees, study_mode, level_id) VALUES ('3c19b957-c0be-84eb-4d64-cadf1eeb64a7'::uuid, 'B.Eng.', 180, 'Frechen (near Cologne)', 'English', '36 Months', '27,770.00 €', 'full_time', '67259672-561c-ac68-a9e8-aef2925a5710'::uuid);
INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('a0c0980a-a30f-2127-df32-29510f7b9d64'::uuid, 'Management and Technology (Bachelor of Engineering) Major: Mechanical Engineering', '3c19b957-c0be-84eb-4d64-cadf1eeb64a7'::uuid, 'Frechen (near Cologne)', '36 Months', 'View Program Description Click to expand Technical products that we rely on in everyday life are continuously developed, designed, and optimized to become indispensable. This progress is driven by the interdisciplinary field of mechatronics, which combines mechanics, electrical engineering, and computer science. Mechatronics is an innovative and future-oriented sector that adapts to evolving technological standards and the needs of tomorrow. It plays a key role in shaping modern industries and advanced technologies. The Bachelor''s degree in Mechatronics (B.Eng.) integrates technical, scientific, and business administration knowledge, providing you with excellent career opportunities after graduation. You will be well-prepared for roles in international manufacturing companies as well as in the rapidly growing German industrial market.', 'HIgher Secondary School Min. 70%
INSERT INTO public.degree_requirement (degree_id, document_type_id, requirement_type) VALUES ('3c19b957-c0be-84eb-4d64-cadf1eeb64a7'::uuid, 'de490609-262a-b222-de1f-8254103db295'::uuid, 'REQUIRED') ON CONFLICT (degree_id, document_type_id) DO NOTHING;
