INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('cfd5a72c-8085-6e7b-1c33-0f1a2bca4e83'::uuid, 'Marketing Management (Bachelor of Arts)', 'c1f854a3-1087-c41e-da9b-8e4eeb6690f3'::uuid, 'Frechen (near Cologne)', '36 Months', 'View Program Description Click to expand Are you full of creative ideas and passionate about marketing? Then the Bachelor''s degree in Marketing Management is the perfect starting point for your professional future. This programme opens doors to a wide range of career opportunities, including market research, product management, sales, and controlling. As a marketing manager, your key role is to understand the market and identify customer needs in order to build strong connections with your brand. You will learn to rethink processes and adapt to evolving market trends. Working in this dynamic environment also means continuously embracing new tools, strategies, and services to stay ahead in the competitive world of marketing.', 'HIgher Secondary School Min. 70%
