INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('5ba41981-8782-d824-6f6e-17468f114fc0'::uuid, 'Management and Technology (Bachelor of Engineering) Major: Energy & Environment', 'a05146c3-2b24-5f00-a987-e017092bc411'::uuid, 'Frechen (near Cologne)', '36 Months', 'View Program Description Click to expand The English-language Bachelor''s programme B.Eng. Management & Technology is designed for international applicants who aim to build careers in the global job market or within internationally operating companies. Graduates of this programme are specialists at the intersection of technology and business. Their expertise is essential wherever technical knowledge and business thinking must be aligned to drive innovation and efficiency. You can choose between two future-oriented specialisations: Energy Management with a focus on hydrogen or Mechanical Engineering – allowing you to tailor your studies according to your interests and strengths.', 'HIgher Secondary School Min. 70%
