INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('db84cc0e-1870-c789-2413-b1b1ae43d158'::uuid, 'Artificial Intelligence (Bachelor of Arts)', '39fa98f5-bd40-ac8f-0566-5b1aa7afab1c'::uuid, 'Düren', '36 Months', 'View Program Description Click to expand The planning, organization, and control of material and information flows along the value chain are essential components of trade in today’s globalized world. Logistics plays a crucial role in ensuring efficiency and smooth operations across industries. With its strong business orientation, this programme also promotes multilingual skills and provides a broad range of professional qualifications. This combination equips you with the expertise required to succeed in a dynamic international environment. After graduating with a B.A. in Logistics Management, you will be prepared to take on specialist and leadership roles, as well as management responsibilities across various sectors of the global logistics and supply chain industry.', 'HIgher Secondary School Min. 70%
