INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('2ff0cab5-df2c-6cdd-d634-e7e1dd29da6a'::uuid, 'International Business Administration (Bachelor of Arts)', '012454f2-1d1a-01a4-5743-bbcf25713372'::uuid, 'Berlin', '36 Months', 'View Program Description Click to expand Team members throughout Europe, customers in the USA, and cooperation partners in Asia – today, entrepreneurial thinking and action extend far beyond national borders. Even medium-sized companies are increasingly operating internationally, creating a demand for professionals with both strong business knowledge and intercultural competence. This programme prepares you to take on responsibility in national and international teams. Whether managing foreign branches, handling international customer relationships in purchasing or sales, developing new locations abroad, addressing personnel-related challenges, or creating global marketing strategies – you will be equipped for diverse roles. The Bachelor''s degree in International Business Administration offers a wide-ranging and cross-functional curriculum, opening up numerous career opportunities in the global business environment. Its key strength lies in the practical combination of business administration specialisations with languages and intercultural management.', 'Higher Secondary School Min. 70%
INSERT INTO public.degree_requirement (degree_id, document_type_id, requirement_type) VALUES ('012454f2-1d1a-01a4-5743-bbcf25713372'::uuid, 'de490609-262a-b222-de1f-8254103db295'::uuid, 'REQUIRED') ON CONFLICT (degree_id, document_type_id) DO NOTHING;
