INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('c18511a1-cefe-c9ca-fb76-fd56d09a5b12'::uuid, 'Digital Business Management (Bachelor of Arts)', '01dcd0a2-9c7c-44af-7df2-db3333988595'::uuid, 'Düren', '36 Months', 'View Program Description Click to expand Self-driving vehicles, thinking machines, intelligent warehouses or web-based administration of buildings via smartphones – in the coming years, our world will be fundamentally transformed. Digitalisation is revolutionising the entire economy and creating innovative job opportunities. Everything can be accessed online, meetings can be held virtually, and content can be shared instantly across platforms. Regardless of time and place, the digital world increasingly mirrors reality – and businesses must adapt to these evolving conditions. Enterprises need highly trained specialists and managers who are fluent in the digital world and capable of driving this transformation. The B.A. Digital Business Management programme prepares you to meet these challenges and succeed in the digital economy.', 'HIgher Secondary School Min. 70%
INSERT INTO public.degree_requirement (degree_id, document_type_id, requirement_type) VALUES ('01dcd0a2-9c7c-44af-7df2-db3333988595'::uuid, 'de490609-262a-b222-de1f-8254103db295'::uuid, 'REQUIRED') ON CONFLICT (degree_id, document_type_id) DO NOTHING;
