INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('ed52d403-fa20-ec27-05d4-781e8ee56b22'::uuid, 'Care & Management (Bachelor of Science)', '566c3451-ba00-50e1-ce61-11be1b185981'::uuid, 'Waldshut', '54 Months', 'View Program Description Click to expand With our practical study model in the Nursing & Management programme, you can combine your nursing training with an academic degree. Not only will you acquire comprehensive scientific skills and learn to work in an evidence-based manner, but you will also receive state recognition as a nursing professional during the course of your studies. In addition, you will strengthen essential personal and social skills such as stress management, emotional intelligence and ethical decision-making processes. Practical skills in counselling and case management round off your studies and prepare you optimally for your future tasks in direct patient care, quality assurance or in responsible management positions.', 'HIgher Secondary School Min. 70%
INSERT INTO public.degree_requirement (degree_id, document_type_id, requirement_type) VALUES ('566c3451-ba00-50e1-ce61-11be1b185981'::uuid, 'de490609-262a-b222-de1f-8254103db295'::uuid, 'REQUIRED') ON CONFLICT (degree_id, document_type_id) DO NOTHING;
