INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('2efba857-4c74-1e98-d4c1-2f5ea709ea53'::uuid, 'Physician Assistance (Bachelor of Science)', 'ac181c6a-e8d1-2cff-d07c-4989916c9fb2'::uuid, 'Waldshut', '36 Months', 'View Program Description Click to expand Whether it involves interviewing and examining patients, performing diagnostic procedures, assisting in surgical interventions, or preparing discharge documentation – many of these responsibilities were traditionally reserved for physicians. Today, with proper authorisation, physician assistants can independently carry out these tasks, making them an essential part of modern healthcare. Physician assistants play a central role in supporting medical teams and enhancing patient care. This programme is designed to equip medical professionals with the necessary skills for these demanding responsibilities while also opening new pathways for career growth in the healthcare sector. The FHM B.Sc. Physician Assistance programme is aligned with the position paper of the German Medical Association (April 2025), focusing on the future development and regulation of the physician assistant profession in Germany.', 'HIgher Secondary School Min. 70%
INSERT INTO public.degree_requirement (degree_id, document_type_id, requirement_type) VALUES ('ac181c6a-e8d1-2cff-d07c-4989916c9fb2'::uuid, 'de490609-262a-b222-de1f-8254103db295'::uuid, 'REQUIRED') ON CONFLICT (degree_id, document_type_id) DO NOTHING;
