INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('d907f046-c7df-57e2-7d6e-549319c957dc'::uuid, 'Sustainability and Climate Management (Master of Arts)', '7c4561de-b2a7-2652-1dea-36d7035cace7'::uuid, 'Düren', '36 Months', 'View Program Description Click to expand Sustainability is not just a megatrend – it is a necessity. The part-time Master''s programme in Sustainability & Climate Management prepares you to successfully tackle the challenges in this rapidly evolving field. This programme offers a unique combination of sustainability, climate, and management, setting it apart in the German-speaking education market. You will gain practical and strategic insights required to drive sustainable transformation in organisations. In addition, key frameworks such as the Corporate Sustainability Reporting Directive (CSRD), the European Sustainability Reporting Standards (ESRS), and alternatively the Voluntary ESRS for non-listed SMEs (VSME) are covered to help you understand and adapt to the growing requirements in sustainability reporting.', '3 or 4 year Bachelor''s Degree Min. 55%
