INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('3c765925-1bab-c6f4-e23e-782faea3fcff'::uuid, 'International Technology Transfer Management (Master of Science)', '16d1defb-232e-1d7a-b9b2-957406b24286'::uuid, 'Berlin', '24 Months', 'View Program Description Click to expand The M.Sc. International Technology Transfer Management (ITTM) is a unique programme designed for individuals aiming to build an internationally oriented management career. Graduates typically work in multinational companies and operate within global business environments. This programme is ideal for Bachelor’s degree holders in engineering and business administration, providing them with the knowledge and skills required to manage and transfer technology across international markets. Applicants from other academic backgrounds who are interested in pursuing a career in International Technology Transfer Management are also encouraged to apply, making this programme diverse and interdisciplinary.', '3 or 4 year Bachelor''s Degree Min. 55%
