INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('538f5c18-d367-3737-3351-44a6174f9757'::uuid, 'International Management (Master of Arts)', '0decb775-c3a1-fe64-a3df-34d9d60a6068'::uuid, 'Berlin', '24 Months', 'View Program Description Click to expand Video and phone conferences with team members in the United Kingdom and Brazil, production facilities in South Korea, cooperation partners in China, and customers in the USA and Australia – today’s global business environment is highly interconnected. This increasing interdependence of world economies requires companies to operate internationally and collaborate across borders more than ever before. As a result, there is a growing demand for professionals who can navigate global markets effectively. This programme prepares you to become an international manager with a strong foundation in business, combined with essential intercultural competencies and language skills needed to succeed in a globalised world.', '3 or 4 year Bachelor''s Degree Min. 55%
