INSERT INTO public.degree (id, name, credits, location, language_of_study, duration, fees, study_mode, level_id) VALUES ('1f3d8613-307e-2c84-9131-fd8f27423893'::uuid, 'MBA', NULL, 'Berlin', NULL, '18 Months', '16,520.00 €', 'full_time', 'efc8989d-c954-13b7-df88-92c7f9d01287'::uuid);
INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('3a15b1ef-402e-409b-277f-6e7c82257660'::uuid, 'Master of Business Administration (MBA) – General Technology Management Major: Environment and Energy Management', '1f3d8613-307e-2c84-9131-fd8f27423893'::uuid, 'Berlin', '18 Months', 'View Program Description Click to expand In today’s globally connected economy, innovation plays a decisive role in determining competitiveness and business success. Internationalisation and globalisation are increasing the pressure to innovate, not only for large corporations but also for small and medium-sized enterprises (SMEs). Future managers will be challenged to keep their organisations competitive by developing market-creating innovations and implementing efficiency-enhancing strategies. These capabilities are essential to sustaining long-term growth and success. Only through continuous innovation can Germany’s economic backbone, the “Mittelstand,” with its numerous global market leaders and the renowned “Made in Germany” quality label, maintain its strong position in the global economy.', '3 or 4 year Bachelor''s Degree Min. 55%
