INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('fa720d07-79db-a386-e27c-db086e70f007'::uuid, 'Global SMEs (Master of Arts)', '85f55fa4-29b0-9a5f-9c00-1d054936ad29'::uuid, 'Berlin', '24 Months', 'View Program Description Click to expand As a business graduate, the M.A. Global Mittelstand master''s programme opens up a wide range of career opportunities in the business world. With flexible study locations and part-time options, it is perfectly suited to support your professional development. If you hold a bachelor’s degree in business and aspire to transform the world of German SMEs, this programme offers you the ideal platform. You will gain in-depth knowledge of how innovation and sustainability drive success in a globalised economy. Alongside strengthening your intercultural competencies, you will explore modern leadership approaches and develop the skills needed to actively shape the future of small and medium-sized enterprises. Become an expert in navigating the challenges and opportunities of a connected world.', '3 or 4 year Bachelor''s Degree Min. 55%
