INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('6394cf10-d010-e675-da76-b3f5d47cf29f'::uuid, 'Master of Business Administration (MBA) – General Technology Management Major: Data Science', '6f8c525c-d5a1-810c-e7bb-a1ee2bff48da'::uuid, 'Berlin', '18 Months', 'View Program Description Click to expand The increasing interdependence of global economies is intensifying international competition and requiring companies to act with greater urgency and strategic focus. Businesses that aim to succeed today and in the future must move beyond outdated management approaches. The next generation of managers and leaders must be equipped with innovative general management skills to navigate complex global environments. At the same time, specialised technological knowledge is becoming essential to drive growth and remain competitive. This programme prepares you to meet these challenges by combining modern management practices with relevant technological insights, enabling you to lead effectively in international organisations and anticipate future developments.', '3 or 4 year Bachelor''s Degree Min. 55%
