INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('ed37bca9-dbfc-5552-8533-0ce9c8312c17'::uuid, 'Digital Transformation Management (Master of Science)', 'cede204c-e25e-522a-bd4b-84baf51ea0a5'::uuid, 'Düren', '18 Months', 'View Program Description Click to expand Good news for forward thinkers: the M.Sc. Digital Transformation Management programme is available in both part-time and full-time formats, making it highly flexible for professionals and aspiring leaders. This programme is specifically designed to meet the needs of specialists and managers involved in digital transformation. In today’s fast-changing environment, companies must continuously innovate and adapt to stay competitive. With this programme, you will gain the skills to actively manage transformation processes and position yourself as a pioneer in driving digital change within organisations.', '3 or 4 year Bachelor''s Degree Min. 55%
