INSERT INTO public.course (id, name, degree_id, location, program_length, program_detail, admission_requirements, category, status, is_deleted) VALUES ('98afcc7a-44b4-f6b0-5061-cc1dac2a832b'::uuid, 'Finance and Fintech (Master of Science)', 'd624a573-cdad-cbef-54a3-dc60845b2950'::uuid, 'Düren', '24 Months', 'View Program Description Click to expand You will receive practical training in corporate finance, financial planning and analysis, financial modelling, valuation and FinTech technologies. The focus is on working with real-world company data, practical case studies and tools such as Advanced Excel, Power BI, Python and blockchain applications. A particular highlight is the practice-oriented Master’s thesis, which you will undertake in collaboration with companies or FinTech organisations. At the same time, decision-making, leadership skills and intercultural working are fostered to prepare you for international career paths.', '3 or 4 year Bachelor''s Degree Min. 55%
